const TOKEN = '__CC_EMAIL_FACADE_TOKEN__';
const item = $input.first().json;
const hdr = item.headers || {};
const supplied = hdr['x-cc-token'];
if (supplied !== TOKEN) { throw new Error('cc-email-facade - unauthorized'); }
const body = item.body || {};
if (!body || !body.mode) { throw new Error('cc-email-facade - missing mode'); }
// Attachments are never requested through this facade: Central Command
// ingests text only (attachments are extracted at the gateway).
if (body.include_attachments) { throw new Error('cc-email-facade - attachments are not served through this facade'); }
return [{ json: body }];

// cc-email-facade - the provider REFUSED or FAILED: say which, in the status.
// n8n reports any thrown sub-workflow error as HTTP 500 "Error in workflow",
// which Central Command's failure taxonomy reads as "n8n down" and parks the
// run (DL-205). A refusal the provider states in words is the caller's to act
// on (narrow the query, fix the mode): 422. Anything else - auth, rate limit,
// transport, an unreadable page, a message this list does not know - stays
// an outage: 503, exactly what the caller saw before. Fail-safe is "outage".
const err = $input.first().json.error;
const msg = typeof err === 'string' ? err
  : (err && (err.message || err.description)) ? String(err.message || err.description)
  : JSON.stringify(err ?? 'unknown error');
const REFUSALS = [
  /pagination cap hit/i,                 // list: more than the page cap matches - narrow scope_query
  /rejected the list query \(400\)/i,    // list: the provider could not parse scope_query
  /bad or missing mode/i,                // Validate request
  /requires (scope_query|source_ref)/i,  // Validate request
  /must be (boolean|a positive number)/i // Validate request
];
const status = REFUSALS.some(re => re.test(msg)) ? 422 : 503;
return [{ json: { message: msg.slice(0, 500), status } }];
